# The first books in the catalog with each one's review ratings.
query CatalogRatings($first: Int!) {
  books(first: $first) {
    id
    title
    reviews {
      rating
    }
  }
}

sha256:50d69ec78f7ee81ca104e41aa8991582c:
# An order, its books, and their reviews, for the order screen.
query OrderScreen($orderId: ID!) {
  order(id: $orderId) {
    id
    status
    totalCents
    lines {
      quantity
      book {
        title
        author
        reviews(first: 3) {
          rating
          text
        }
      }
    }
  }
}

sha256:90fda13f833912fbe1d5fa1d4134c41e6:
# Buy books for a customer. Changes data.
mutation PlaceOrder($input: PlaceOrderInput!) {
  placeOrder(input: $input) {
    id
    status
    totalCents
  }
}
